    @Override
    public void setupAnim(WayfarerRenderState state) {
        super.setupAnim(state);
        idle.apply((long) (state.ageInTicks * 50.0F), 1.0F);
        for (int i = 0; i < actions.length; i++) {
            actions[i].apply(state.actions[i], state.ageInTicks);
        }
    }
